type Location = { line: number; column: number };
type Node = TextNode | ValueNode | BlockNode;
type TextNode = { type: "text"; value: string };
type ValueNode = { type: "value"; path: string; escaped: boolean; at: Location };
type BlockNode = {
  type: "block";
  kind: "if" | "each";
  path: string;
  body: Node[];
  alternate: Node[] | null;
  at: Location;
};

type Frame = { block: BlockNode; target: Node[]; elseSeen: boolean };
type Context = { root: unknown; value: unknown; index?: number };

function locationAt(source: string, offset: number): Location {
  const before = source.slice(0, offset);
  const line = before.split("\n").length;
  const lastNewline = before.lastIndexOf("\n");
  return { line, column: offset - lastNewline };
}

function fail(message: string, at: Location): never {
  throw new Error(`${message} at line ${at.line}, column ${at.column}`);
}

function parsePath(value: string, at: Location): string {
  const path = value.trim();
  if (!path) fail("Expected a path", at);
  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Frame[] = [];
  let target = root;
  let cursor = 0;

  const addText = (value: string) => { if (value) target.push({ type: "text", value }); };
  while (cursor < template.length) {
    const start = template.indexOf("{{", cursor);
    if (start < 0) { addText(template.slice(cursor)); break; }
    addText(template.slice(cursor, start));
    const triple = template.startsWith("{{{", start);
    const close = triple ? "}}}" : "}}";
    const contentStart = start + (triple ? 3 : 2);
    const end = template.indexOf(close, contentStart);
    const at = locationAt(template, start);
    if (end < 0) fail("Unclosed tag", at);
    const content = template.slice(contentStart, end).trim();
    cursor = end + close.length;

    if (triple) {
      target.push({ type: "value", path: parsePath(content, at), escaped: false, at });
    } else if (content.startsWith("!")) {
      continue;
    } else if (content === "else") {
      const frame = stack.at(-1);
      if (!frame) fail("else outside a block", at);
      if (frame.elseSeen) fail("Duplicate else", at);
      frame.elseSeen = true;
      frame.block.alternate = [];
      target = frame.block.alternate;
    } else if (content.startsWith("#")) {
      const match = /^#(if|each)\s+(.+)$/.exec(content);
      if (!match) fail("Unknown or malformed block", at);
      const block: BlockNode = { type: "block", kind: match[1] as "if" | "each", path: parsePath(match[2], at), body: [], alternate: null, at };
      target.push(block);
      stack.push({ block, target, elseSeen: false });
      target = block.body;
    } else if (content.startsWith("/")) {
      const name = content.slice(1).trim();
      const frame = stack.at(-1);
      if (!frame) fail(`Unexpected closing block '${name}'`, at);
      if (name !== frame.block.kind) fail(`Mismatched closing block '${name}', expected '${frame.block.kind}'`, at);
      stack.pop();
      target = frame.target;
    } else {
      target.push({ type: "value", path: parsePath(content, at), escaped: true, at });
    }
  }
  const open = stack.at(-1);
  if (open) fail(`Unclosed block '${open.block.kind}'`, open.block.at);
  return root;
}

function resolve(path: string, context: Context): unknown {
  if (path === "this") return context.value;
  if (path === "@index") return context.index;
  const parts = path.split(".");
  let current: any = context.root;
  for (const part of parts) {
    if (current == null || (typeof current !== "object" && typeof current !== "function")) return undefined;
    current = current[part];
  }
  return current;
}

function isTruthy(value: unknown): boolean {
  if (value == null || value === false || value === 0 || value === "") return false;
  return !Array.isArray(value) || value.length > 0;
}

function scalar(value: unknown, at: Location): string {
  if (value == null) return "";
  if (typeof value === "string" || typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") return String(value);
  fail(`Cannot render ${typeof value} as scalar text`, at);
}

function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[char]!);
}

function renderNodes(nodes: Node[], context: Context): string {
  let output = "";
  for (const node of nodes) {
    if (node.type === "text") output += node.value;
    else if (node.type === "value") {
      const value = scalar(resolve(node.path, context), node.at);
      output += node.escaped ? escapeHtml(value) : value;
    } else {
      const value = resolve(node.path, context);
      if (node.kind === "if") output += renderNodes(isTruthy(value) ? node.body : (node.alternate ?? []), context);
      else if (Array.isArray(value) && value.length) {
        value.forEach((item, index) => { output += renderNodes(node.body, { root: context.root, value: item, index }); });
      } else output += renderNodes(node.alternate ?? [], context);
    }
  }
  return output;
}

/** Renders a Mini Template string using the supplied root data object. */
export function render(template: string, data: unknown): string {
  return renderNodes(parse(template), { root: data, value: data });
}
import { expect, test } from "bun:test";
import { render } from "./src/engine";

test("interpolation escapes HTML and preserves whitespace", () => {
  expect(render(" hello {{name}}! ", { name: "<&>\"'" })).toBe(" hello &lt;&amp;&gt;&quot;&#39;! ");
  expect(render("{{{name}}}", { name: "<b>" })).toBe("<b>");
});
test("conditionals nest and use defined truthiness", () => {
  expect(render("{{#if a}}A{{#if b}}B{{else}}C{{/if}}{{else}}D{{/if}}", { a: true, b: false })).toBe("AC");
  expect(render("{{#if a}}yes{{else}}no{{/if}}", { a: [] })).toBe("no");
});
test("each supports this, indexes, root fallback, nesting, and else", () => {
  expect(render("{{#each items}}{{@index}}:{{this}}/{{title}};{{/each}}", { title: "T", items: ["a", "b"] })).toBe("0:a/T;1:b/T;");
  expect(render("{{#each rows}}{{#each cols}}{{this}}{{/each}}{{/each}}", { rows: [[1, 2], [3]] })).toBe("123");
  expect(render("{{#each items}}x{{else}}empty{{/each}}", { items: [] })).toBe("empty");
});
test("missing values are empty and non-scalars fail", () => {
  expect(render("x{{missing}}y", {})).toBe("xy");
  expect(() => render("{{value}}", { value: {} })).toThrow("Cannot render object");
});
test("reports structural errors with locations", () => {
  expect(() => render("{{else}}", {})).toThrow("line 1, column 1");
  expect(() => render("{{#if a}}{{/each}}", {})).toThrow("Mismatched");
  expect(() => render("{{#if a}}", {})).toThrow("Unclosed block");
  expect(() => render("{{#wat a}}{{/wat}}", {})).toThrow("Unknown");
});

