  return path;
}

function parse(template: string): Node[] {
  const root: Node[] = [];
  const stack: Frame[] = [];
  let target = root;
  let cursor = 0;

  const addText = (value: string) => { if (value) target.push({ type: "text", value }); };
  while (cursor < template.length) {
    const start = template.indexOf("{{", cursor);
